const BASE = 'http://localhost:4322/words-of-the-day/practice/';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
page.on('console', (msg) => {
  if (msg.type() === 'error') console.log('PAGE ERROR:', msg.text().slice(0, 300));
});
page.on('pageerror', (err) => console.log('PAGE EXCEPTION:', String(err).slice(0, 300)));

await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="stress"]');
await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });

const result = await page.evaluate(() => {
  const prompt = document.querySelector('[data-testid="practice-form-prompt"]');
  const stress = document.querySelector('[data-testid="practice-stress"]');
  const word = document.querySelector('.practice-stress-word');
  const rect = (el) => {
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), width: Math.round(r.width) };
  };
  const pr = rect(prompt);
  const wr = rect(word);
  const gap = pr && wr ? wr.top - pr.bottom : null;
  return {
    url: location.href,
    prompt: pr,
    stress: rect(stress),
    word: wr,
    gapBetweenPromptAndWord: gap,
    promptText: prompt ? prompt.textContent.replace(/\s+/g, ' ').slice(0, 90) : null,
    wordText: word ? word.textContent.replace(/\s+/g, ' ').slice(0, 60) : null,
    stressClasses: stress ? stress.className : null,
  };
});

console.log(JSON.stringify(result, null, 2));

