import { chromium } from 'playwright';

const BASE = 'http://localhost:4322/words-of-the-day/practice/';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
page.on('pageerror', (err) => console.log('PAGE EXCEPTION:', String(err).slice(0, 400)));

await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="stress"]');
await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });

const result = await page.evaluate(() => {
  const stage = document.querySelector('.lexicon-stress');
  const prompt = document.querySelector('[data-testid="practice-form-prompt"]');
  const cs = (el, props) => {
    const s = getComputedStyle(el);
    const out = {};
    for (const p of props) out[p] = s[p];
    return out;
  };
  const childrenInfo = [...(stage ? stage.children : [])].map((child) => {
    const r = child.getBoundingClientRect();
    return {
      tag: child.tagName,
      cls: child.className,
      top: Math.round(r.top),
      bottom: Math.round(r.bottom),
      height: Math.round(r.height),
      text: child.textContent.replace(/\s+/g, ' ').slice(0, 70),
    };
  });
  return {
    stressOuterHTML: stage ? stage.outerHTML : null,
    childrenInfo,
    promptComputed: cs(prompt, ['margin', 'padding', 'font-size', 'line-height', 'display', 'height', 'min-height', 'flex-direction', 'align-items']),
    stressComputed: cs(stage, ['display', 'gap', 'grid-template-rows', 'align-items', 'justify-items', 'min-height']),
  };
});

console.log(JSON.stringify(result, null, 2));
await browser.close();

import { chromium } from 'playwright';

