const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="stress"]');
await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });

const result = await page.evaluate(() => {
  const prompt = document.querySelector('[data-testid="practice-form-prompt"]');
  const word = document.querySelector('.practice-stress-word');
  const pr = prompt.getBoundingClientRect();
  const wr = word.getBoundingClientRect();
  const spans = [...prompt.querySelectorAll('*')].map((el) => {
    const r = el.getBoundingClientRect();
    return {
      tag: el.tagName,
      cls: typeof el.className === 'string' ? el.className : '',
      top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), width: Math.round(r.width),
      text: el.textContent.replace(/\s+/g, ' ').slice(0, 50),
    };
  });
  const htmlFontSize = getComputedStyle(document.documentElement).fontSize;
  const mcq = getComputedStyle(prompt);
  const mcqRules = [...document.styleSheets].flatMap((sheet) => {
    try { return [...sheet.cssRules]; } catch { return []; }
  }).filter((rule) => {
    if (rule.style && /mc-q|lexicon-choice-prompt/.test(rule.selectorText || '')) {
      return rule.selectorText;
    }
    return false;
  }).map((rule) => ({ selector: rule.selectorText, css: rule.style.cssText }));
  return {
    promptRect: { top: Math.round(pr.top), bottom: Math.round(pr.bottom), height: Math.round(pr.height) },
    wordRect: { top: Math.round(wr.top), height: Math.round(wr.height) },
    spans,
    htmlFontSize,
    promptFont: mcq.fontSize, promptLineHeight: mcq.lineHeight, promptDisplay: mcq.display,
    mcqRules,
  };
});
console.log(JSON.stringify(result, null, 2));
await browser.close();

